// Transparent Windows entrypoints for the official portable OSS CAD binaries.
// No simulation results or exit codes are generated by this adapter.
using System;
using System.IO;
using System.Text;
using System.Diagnostics;
using System.Collections.Generic;
class ToolLauncher {
    static string Quote(string value) {
        var result = new StringBuilder("\""); int slashes=0;
        foreach(char c in value) {
            if(c=='\\') { slashes++; continue; }
            if(c=='"') { result.Append('\\',slashes*2+1); result.Append(c); }
            else { result.Append('\\',slashes); result.Append(c); }
            slashes=0;
        }
        result.Append('\\',slashes*2); result.Append('"'); return result.ToString();
    }
    static int Main(string[] args) {
        try {
            string root=Environment.GetEnvironmentVariable("YOSYSHQ_ROOT");
            if(String.IsNullOrEmpty(root)) throw new Exception("Activate OSS CAD Suite first");
            string tool=Path.GetFileNameWithoutExtension(System.Reflection.Assembly.GetExecutingAssembly().Location);
            string binary=tool=="verilator"?"verilator_bin":tool;
            var forwarded=new List<string>(); string ivl=Path.Combine(root,"lib","ivl");
            if(tool=="iverilog") forwarded.Add("-B"+ivl);
            if(tool=="vvp") forwarded.Add("-M"+ivl);
            forwarded.AddRange(args);
            var quoted=new List<string>(); foreach(string arg in forwarded) quoted.Add(Quote(arg));
            var info=new ProcessStartInfo(Path.Combine(root,"bin",binary+".exe"),String.Join(" ",quoted.ToArray()));
            info.UseShellExecute=false; info.CreateNoWindow=true;
            info.RedirectStandardOutput=true; info.RedirectStandardError=true;
            using(var process=new Process()) {
                process.StartInfo=info;
                process.OutputDataReceived+=(sender,e)=> { if(e.Data!=null) Console.Out.WriteLine(e.Data); };
                process.ErrorDataReceived+=(sender,e)=> { if(e.Data!=null) Console.Error.WriteLine(e.Data); };
                process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();
                process.WaitForExit();return process.ExitCode;
            }
        } catch(Exception ex) { Console.Error.WriteLine(ex.ToString()); return 127; }
    }
}
